import{_ as o,o as t,c as n,a5 as a}from"./chunks/framework.DJo0M80U.js";const y=JSON.parse('{"title":"组合继承","description":"组合继承（ combination inheritance ），有时候也叫做伪经典继承，指的是将原型链和借用构造函数的技术组合到一块，从而发挥二者之长的一种继承方式。 这是最常用的继承模式。而且， instanceof 和 isPrototypeOf() 也能够用于识别基于组合继。","frontmatter":{"title":"组合继承","date":"2026-08-11T00:00:00.000Z","categories":["JavaScript 系统教程"],"tags":["JavaScript","前端","教程","OneNote","对象、数组与函数"],"description":"组合继承（ combination inheritance ），有时候也叫做伪经典继承，指的是将原型链和借用构造函数的技术组合到一块，从而发挥二者之长的一种继承方式。 这是最常用的继承模式。而且， instanceof 和 isPrototypeOf() 也能够用于识别基于组合继。","sidebarWeight":153,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/b-原生js/面向对象程序设计/(80m)继承/(20m)组合继承.md"},"headers":[],"relativePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(20m)组合继承.md","filePath":"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(20m)组合继承.md"}'),c={name:"posts/JavaScript系统教程/03-对象、数组与函数/(80m)继承/(20m)组合继承.md"};function p(s,e,r,i,l,u){return t(),n("div",null,[...e[0]||(e[0]=[a('<div><h1 id="组合继承" tabindex="-1">组合继承 <a class="header-anchor" href="#组合继承" aria-label="Permalink to &quot;组合继承&quot;">​</a></h1><blockquote><p>本节目标：理解“组合继承”的核心思路，并能把它用于实际开发或面试表达。 组合继承（<code>combination inheritance</code>），有时候也叫做伪经典继承，指的是将原型链和借用构造函数的技术组合到一块，从而发挥二者之长的一种继承方式。</p></blockquote><p>==这是最常用的继承模式。而且，==<code>instanceof</code>==和==<code>isPrototypeOf()</code>==也能够用于识别基于组合继承创建的对象。==</p><p><strong>思路：</strong></p><ul><li>父类实例非共享的属性，子类实例通过借用父类构造函数来实现；</li><li>父类实例中可共享的属性，子类实例通过指定子类构造函数原型为父类实例来实现。</li></ul><p><strong>注意：</strong></p><ul><li>指定子类特有非共享属性：调用父类构造函数之后再指定子类特有的属性以防覆盖；</li><li>指定子类特有共享属性：指定子类构造函数原型之后再指定子类原型上的自有方法，这些方法只供子类实例共享。</li></ul><p>如下： function SuperType(name) { this.name = name; this.colors = [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;]; } SurperType.prototype.sayName = function () { console.log(this.name); } function SubType(name, age) { //继承属性 SurperType.call(this, name); this.age = 29; //继承方法 SubType.prototype = new SuperType(); SubType.prototype.sayAge = function () { console.log(this.age); } } var instance1 = new SubType(&#39;Nicholas&#39;, 29); instance1.colors.push(&#39;black&#39;); console.log(instance1.colors);//&#39;red,blue,green,black&#39; instance1.sayName();//&#39;Nicholas&#39; var instance2 = new SubType(&#39;Greg&#39;, 27); console.log(instance2.colors);//&#39;red,blue,green&#39; instance2.sayName();//&#39;Greg&#39; instance2.sayAge();//27</p><p><strong>组合继承的问题：</strong></p><ul><li>组合继承无论什么情况下，都会调用两次超类构造函数：一次是在创建子类型原型的时候，另一次是在子类型构造函数内部。</li><li>子类在指定子类构造函数原型的时候会继承超类实例的所有实例属性；但在创建子类实例时，又在子类构造函数中调用超类构造函数时，又重新定义了这些属性，这样子类实例自身的同名属性屏蔽了对原型对象上同名属性的访问。看码：</li></ul><p>function SuperType(name) { this.name = name; this.colors = [&#39;red&#39;, &#39;blue&#39;, &#39;green&#39;] } SuperType.prototype.sayName = function () { console.log(this.name); } function SubType(name, age) { //第二次调用SuperType() SuperType.call(this,name); this.age = age; } //第一次调用SuperType() SubType.prototype = new SuperType(); SubType.prototype.constructor = SubType; SubType.prototype.sayAge = function () { console.log(this.age); } 在第一次调用<code>SuperType</code>构造函数时，<code>SubType.prototype</code>会得到两个属性：<code>name</code>和<code>colors;</code>它们都是<code>SuperType</code>的实例属性，只不过现在位于<code>SubType</code>的原型中。当调用<code>Subtype</code>构造函数时，又会调用一次<code>SuperType</code>构造函数，这一次又在新对象上创建了实例属性<code>name</code>和<code>colors</code>。于是，这两个属性就屏蔽了原型中的两个同名属性。</p></div>',1)])])}const m=o(c,[["render",p]]);export{y as __pageData,m as default};
